using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
namespace ServiceGameV2.Editor {public static class ServiceWheelPreview {public static void Run(){EditorSceneManager.OpenScene("Assets/Scenes/HollisCounty.unity");var s=Object.FindAnyObjectByType<CountyScene>();s.Cockpit.SetActive(true);var camera=s.View;camera.transform.SetParent(s.DriverSeat,false);camera.transform.localPosition=Vector3.zero;camera.transform.localRotation=Quaternion.Euler(29,0,0);camera.cullingMask=~(1<<8);camera.fieldOfView=68;camera.nearClipPlane=.035f;var wheel=s.SteeringWheel.Find("Authored leather steering");var render=new RenderTexture(1280,720,24);camera.targetTexture=render;render.Create();int i=0;foreach(var angles in new[]{new Vector3(0,0,0),new Vector3(40,0,180),new Vector3(70,0,180),new Vector3(-35,0,0)}){wheel.localRotation=Quaternion.Euler(angles);camera.Render();RenderTexture.active=render;var tex=new Texture2D(1280,720,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1280,720),0,0);tex.Apply();File.WriteAllBytes(Path.Combine(Directory.GetParent(Application.dataPath).Parent.FullName,"wheel-preview-"+i+++".png"),tex.EncodeToPNG());Object.DestroyImmediate(tex);}camera.targetTexture=null;RenderTexture.active=null;render.Release();}}
}
